SET FOREIGN_KEY_CHECKS=0; SET NAMES utf8mb4;
-- IAM/RBAC (Secuencia 1 - creacion usuarios.sql, con el fix de nombre de rol
-- 'viewer'->'Visor' y las columnas reset_token_* de la Secuencia 9). Este
-- bloque estuvo desactualizado (una version legacy sin personas/estados que
-- provoco un 500 en /api/auth/login en un despliegue nuevo) hasta que se
-- sincronizo aqui.
CREATE TABLE cat_paises(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo_iso CHAR(2) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL UNIQUE,activo TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cat_tipos_documento(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clave VARCHAR(20) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL,descripcion VARCHAR(255),activo TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cat_estados_usuario(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clave VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(60) NOT NULL,descripcion VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE personas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tipo_documento_id INT UNSIGNED NOT NULL,pais_id INT UNSIGNED NOT NULL,nombre VARCHAR(100) NOT NULL,apellido_paterno VARCHAR(100) NOT NULL,apellido_materno VARCHAR(100) NOT NULL,fecha_nacimiento DATE NOT NULL,curp CHAR(18) NOT NULL UNIQUE,rfc VARCHAR(13),email VARCHAR(255) NOT NULL UNIQUE,telefono VARCHAR(20),creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,FOREIGN KEY(tipo_documento_id) REFERENCES cat_tipos_documento(id),FOREIGN KEY(pais_id) REFERENCES cat_paises(id),INDEX idx_nombre(apellido_paterno,apellido_materno,nombre),INDEX idx_email(email),INDEX idx_deleted(deleted_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE roles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(50) NOT NULL UNIQUE,descripcion VARCHAR(255),activo TINYINT(1) NOT NULL DEFAULT 1,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE permisos(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,modulo VARCHAR(50) NOT NULL,accion VARCHAR(50) NOT NULL,descripcion VARCHAR(255),creado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_modulo_accion(modulo,accion))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE permisos_rol(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rol_id INT UNSIGNED NOT NULL,permiso_id INT UNSIGNED NOT NULL,creado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_rol_permiso(rol_id,permiso_id),FOREIGN KEY(rol_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permiso_id) REFERENCES permisos(id) ON DELETE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE usuarios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,persona_id INT UNSIGNED NOT NULL UNIQUE,rol_id INT UNSIGNED NOT NULL,estado_id INT UNSIGNED NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,salt VARCHAR(64),intentos_fallidos TINYINT NOT NULL DEFAULT 0,bloqueado_hasta DATETIME,reset_token_hash VARCHAR(128),reset_token_expires_at DATETIME,ultimo_login DATETIME,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,FOREIGN KEY(persona_id) REFERENCES personas(id) ON DELETE RESTRICT,FOREIGN KEY(rol_id) REFERENCES roles(id) ON DELETE RESTRICT,FOREIGN KEY(estado_id) REFERENCES cat_estados_usuario(id) ON DELETE RESTRICT,INDEX idx_username(username),INDEX idx_deleted(deleted_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE usuarios_hist(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,rol_id INT UNSIGNED NOT NULL,estado_id INT UNSIGNED NOT NULL,password_hash VARCHAR(255) NOT NULL,salt VARCHAR(64),intentos_fallidos TINYINT NOT NULL,bloqueado_hasta DATETIME,operacion ENUM('UPDATE','DELETE') NOT NULL,modificado_por INT UNSIGNED,fecha_operacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_usuario(usuario_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sesiones(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,token VARCHAR(255) NOT NULL UNIQUE,ip_address VARCHAR(45),user_agent VARCHAR(512),expira_en DATETIME NOT NULL,cerrada_en DATETIME,motivo_cierre ENUM('LOGOUT','EXPIRACION','ADMIN','OTRO'),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,INDEX idx_token(token),INDEX idx_expira_en(expira_en),INDEX idx_usuario(usuario_id,cerrada_en))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE intentos_login(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED,exitoso TINYINT(1) NOT NULL DEFAULT 0,ip_address VARCHAR(45),user_agent VARCHAR(512),descripcion VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL,INDEX idx_usuario_fecha(usuario_id,created_at),INDEX idx_ip_fecha(ip_address,created_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE auditoria_cambios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tabla_nombre VARCHAR(64) NOT NULL,registro_id INT UNSIGNED NOT NULL,operacion ENUM('INSERT','UPDATE','DELETE') NOT NULL,datos_anteriores JSON,datos_nuevos JSON,usuario_id INT UNSIGNED,ip_address VARCHAR(45),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL,INDEX idx_tabla_registro(tabla_nombre,registro_id),INDEX idx_usuario(usuario_id),INDEX idx_fecha(created_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE apariencia(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL UNIQUE,modo_oscuro TINYINT(1) NOT NULL DEFAULT 0,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TRIGGER IF EXISTS trg_usuarios_before_update;
CREATE TRIGGER trg_usuarios_before_update BEFORE UPDATE ON usuarios FOR EACH ROW INSERT INTO usuarios_hist(usuario_id,rol_id,estado_id,password_hash,salt,intentos_fallidos,bloqueado_hasta,operacion,modificado_por) VALUES(OLD.id,OLD.rol_id,OLD.estado_id,OLD.password_hash,OLD.salt,OLD.intentos_fallidos,OLD.bloqueado_hasta,'UPDATE',NEW.modificado_por);
DROP TRIGGER IF EXISTS trg_usuarios_before_delete;
CREATE TRIGGER trg_usuarios_before_delete BEFORE DELETE ON usuarios FOR EACH ROW INSERT INTO usuarios_hist(usuario_id,rol_id,estado_id,password_hash,salt,intentos_fallidos,bloqueado_hasta,operacion,modificado_por) VALUES(OLD.id,OLD.rol_id,OLD.estado_id,OLD.password_hash,OLD.salt,OLD.intentos_fallidos,OLD.bloqueado_hasta,'DELETE',OLD.modificado_por);
