INSERT IGNORE INTO roles(nombre,descripcion) VALUES('superadmin','Acceso total al sistema y configuraciones'),('admin','Administración de usuarios y expedientes generales'),('editor','Captura, foliado y modificación de documentos'),('Visor','Consulta y visualización de expedientes sin permisos de edición');
