CREATE TABLE empresas_chinas(id INT UNSIGNED NOT NULL AUTO_INCREMENT,codigo VARCHAR(20) NOT NULL,nombre VARCHAR(180) NOT NULL,representante_legal VARCHAR(180),correo_electronico VARCHAR(180),telefono VARCHAR(30),fecha_registro DATE,etapa_actual TINYINT UNSIGNED NOT NULL DEFAULT 1,estado ENUM('en_proceso','pendiente','finalizada','archivada') NOT NULL DEFAULT 'en_proceso',progreso_pct TINYINT UNSIGNED NOT NULL DEFAULT 0,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,PRIMARY KEY(id),UNIQUE KEY uq_ec_codigo(codigo),KEY idx_ec_estado(estado),KEY idx_ec_deleted(deleted_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE empresa_china_requisitos(id INT UNSIGNED NOT NULL AUTO_INCREMENT,empresa_china_id INT UNSIGNED NOT NULL,requisito_id SMALLINT UNSIGNED NOT NULL,documento_id INT UNSIGNED,valor_texto TEXT,completado TINYINT(1) NOT NULL DEFAULT 0,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,PRIMARY KEY(id),UNIQUE KEY uq_ecr(empresa_china_id,requisito_id),KEY idx_ecr_deleted(deleted_at),CONSTRAINT fk_ecr_empresa FOREIGN KEY(empresa_china_id) REFERENCES empresas_chinas(id) ON DELETE CASCADE,CONSTRAINT fk_ecr_requisito FOREIGN KEY(requisito_id) REFERENCES etapa_requisitos(id),CONSTRAINT fk_ecr_documento FOREIGN KEY(documento_id) REFERENCES documentos(id) ON DELETE SET NULL)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE empresa_china_etapa_checklist(id INT UNSIGNED NOT NULL AUTO_INCREMENT,empresa_china_id INT UNSIGNED NOT NULL,etapa_num TINYINT UNSIGNED NOT NULL,completada TINYINT(1) NOT NULL DEFAULT 0,completada_en DATETIME,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_ecec(empresa_china_id,etapa_num),CONSTRAINT fk_ecec_empresa FOREIGN KEY(empresa_china_id) REFERENCES empresas_chinas(id) ON DELETE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE configuracion_notificaciones(id INT UNSIGNED NOT NULL AUTO_INCREMENT,empresa_id INT UNSIGNED NOT NULL,tipo VARCHAR(80) NOT NULL,dia_del_mes TINYINT UNSIGNED NOT NULL,activa TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY(id),KEY idx_cn_empresa(empresa_id),CONSTRAINT fk_cn_empresa FOREIGN KEY(empresa_id) REFERENCES empresas(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Configuracion alertas FIEL (Secuencia 8 - configuracion alertas fiel.sql):
-- singleton (id=1) con los dias de anticipacion del job de vencimientos de
-- FIEL, configurable por admin/superadmin desde el modulo Configuracion.
CREATE TABLE configuracion_alertas_fiel(id TINYINT UNSIGNED NOT NULL,dias_anticipacion TINYINT UNSIGNED NOT NULL DEFAULT 3,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO configuracion_alertas_fiel(id,dias_anticipacion) VALUES(1,3);
-- Notificaciones (Secuencia 3 - notificaciones.sql): generica y reutilizable
-- via origen_tabla/origen_id; hoy alimentada por el job de vencimientos FIEL.
CREATE TABLE notificaciones(id INT UNSIGNED NOT NULL AUTO_INCREMENT,usuario_id INT UNSIGNED NOT NULL,tipo VARCHAR(60) NOT NULL,origen_tabla VARCHAR(60) NOT NULL,origen_id INT UNSIGNED NOT NULL,dias_restantes TINYINT NOT NULL,titulo VARCHAR(200) NOT NULL,cuerpo VARCHAR(500) NOT NULL,ruta VARCHAR(300) NOT NULL,leida TINYINT(1) NOT NULL DEFAULT 0,leida_en DATETIME,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,PRIMARY KEY(id),KEY idx_notif_usuario(usuario_id,deleted_at,leida),KEY idx_notif_origen(origen_tabla,origen_id,usuario_id,dias_restantes,created_at),CONSTRAINT fk_notif_usuario FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Actividad (Secuencia 5 - actividad.sql): bitacora legible de acciones de
-- usuarios (crear/editar/eliminar/restaurar/login/logout). Distinta de
-- auditoria_cambios (diffs JSON tecnicos de la Secuencia 1, ya creada arriba).
CREATE TABLE actividad_log(id INT UNSIGNED NOT NULL AUTO_INCREMENT,usuario_id INT UNSIGNED,modulo VARCHAR(50) NOT NULL,accion VARCHAR(30) NOT NULL,descripcion VARCHAR(255) NOT NULL,referencia_tabla VARCHAR(64),referencia_id INT UNSIGNED,ip_address VARCHAR(45),creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_actividad_usuario_fecha(usuario_id,created_at),KEY idx_actividad_modulo(modulo),KEY idx_actividad_fecha(created_at),CONSTRAINT fk_actividad_usuario FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO permisos(nombre,modulo,accion,descripcion) VALUES('actividad.leer','ACTIVIDAD','LEER','Consultar la bitacora de actividad del sistema');
INSERT IGNORE INTO permisos_rol(rol_id,permiso_id) SELECT r.id,p.id FROM roles r JOIN permisos p ON 1=1 WHERE r.nombre IN('superadmin','admin','editor','Visor') AND p.nombre='actividad.leer';
-- Facturas HL (Secuencia 6 - facturas hl.sql): modulo espejo de facturas
-- (ARDUM/Secuencia 2) pero para Hegewisch Lopez, la consultora -- no para
-- propietarios de condominio. Por eso no referencia propietarios: usa un
-- campo de texto libre `cliente`. Reutiliza la fila de empresas id=3
-- ('Hegewisch Lopez', sembrada arriba junto al resto de `empresas`) solo
-- como bucket de documentos.empresa_id al subir comprobantes; no se expone
-- como "empresa" navegable en el frontend.
CREATE TABLE facturas_hl(id INT UNSIGNED NOT NULL AUTO_INCREMENT,cliente VARCHAR(180) NOT NULL,fecha DATE NOT NULL,comprobante_id INT UNSIGNED,creado_por INT UNSIGNED,modificado_por INT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME,PRIMARY KEY(id),KEY idx_facturas_hl_fecha(fecha),KEY idx_facturas_hl_deleted(deleted_at),CONSTRAINT fk_facturas_hl_comprobante FOREIGN KEY(comprobante_id) REFERENCES documentos(id) ON DELETE SET NULL)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
